import csv, collections
data = collections.defaultdict(dict)
targets = {
 'c1021e2f-bb67-5120-895b-3a425fb6ff0a':'temp',
 '131a6a13-5101-5d88-a675-688386d58b1f':'cool_sp',
 '581c2206-b265-5578-9b1e-422601278628':'heat_sp',
}
with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        tid = row['timeseries_id']
        if tid in targets and row['timestamp'].startswith('2018-01-06'):
            data[targets[tid]][row['timestamp']] = float(row['value'])
print(len(data['temp']), len(data['cool_sp']), len(data['heat_sp']))
for k in data:
    print(k, sorted(data[k].items())[:3])
